from collections import Counter
import math
import statistics

def report_metrics(scores, tracks, capacity):
    return {
        'python_count': Counter(tracks)['Python'],
        'median_score': statistics.median(scores),
        'groups': math.ceil(len(scores) / capacity),
    }

print(report_metrics([2, 4, 4, 5, 15], ['Python', 'SQL', 'Python', 'SQL', 'Python'], 2))

